/* Canonical pure scorer source. Its browser copy is generated by sync-v2-visual-scorer.mjs. */
export type V2VisualKind = 'money.allocation.v2' | 'math.number-line.whole.v2' | 'math.number-line.fraction.v2' | 'math.fraction-area.v2' | 'math.bar-model.structure.v2' | 'math.bar-model.answer.v2' | 'math.schema-diagram.structure.v2' | 'math.schema-diagram.slots.v2' | 'math.schema-diagram.answer.v2' | 'math.worked-example.v2' | 'math.function-machine.v2' | 'math.cpa-count.v2';
export type V2VisualVerdict = 'invalid' | 'valid' | 'review' | 'met';

function record(value: unknown): value is Record<string, unknown> {
  return typeof value === 'object' && value !== null && !Array.isArray(value);
}

function fields(value: unknown, names: readonly string[]): value is Record<string, unknown> {
  return record(value) && Object.keys(value).length === names.length && names.every((name) => Object.hasOwn(value, name));
}

function whole(value: unknown): value is number {
  return typeof value === 'number' && Number.isSafeInteger(value);
}

/** A missing rubric checks only the semantic response; the browser never receives hidden answers. */
export function scoreV2Visual(kind: V2VisualKind, payload: unknown, response: unknown, rubric?: unknown): V2VisualVerdict {
  switch (kind) {
    case 'money.allocation.v2': {
      if (!fields(payload, ['total', 'step']) || !whole(payload.total) || payload.total <= 0
        || !whole(payload.step) || payload.step <= 0 || payload.total % payload.step !== 0
        || !fields(response, ['save', 'spend', 'share'])) return 'invalid';
      for (const pocket of ['save', 'spend', 'share']) {
        const value = response[pocket];
        if (!whole(value) || value < 0 || value > payload.total || value % payload.step !== 0) return 'invalid';
      }
      if (response.save as number + (response.spend as number) + (response.share as number) !== payload.total) return 'invalid';
      if (rubric === undefined) return 'valid';
      if (!fields(rubric, ['minimumSave']) || !whole(rubric.minimumSave)
        || rubric.minimumSave < 0 || rubric.minimumSave > payload.total || rubric.minimumSave % payload.step !== 0) return 'invalid';
      return (response.save as number) >= rubric.minimumSave ? 'met' : 'review';
    }
    case 'math.number-line.whole.v2': {
      if (!fields(payload, ['minimum', 'maximum', 'step']) || !whole(payload.minimum) || payload.minimum < 0
        || !whole(payload.maximum) || payload.maximum <= payload.minimum || !whole(payload.step) || payload.step <= 0
        || (payload.maximum - payload.minimum) % payload.step !== 0 || !fields(response, ['value'])
        || typeof response.value !== 'string' || !/^(0|[1-9]\d*)$/.test(response.value)) return 'invalid';
      const value = Number(response.value);
      if (!whole(value) || value < payload.minimum || value > payload.maximum || (value - payload.minimum) % payload.step !== 0) return 'invalid';
      if (rubric === undefined) return 'valid';
      if (!fields(rubric, ['target']) || !whole(rubric.target) || rubric.target < payload.minimum
        || rubric.target > payload.maximum || (rubric.target - payload.minimum) % payload.step !== 0) return 'invalid';
      return value === rubric.target ? 'met' : 'review';
    }
    case 'math.number-line.fraction.v2': {
      if (!fields(payload, ['maximumWhole', 'divisions']) || !whole(payload.maximumWhole) || (payload.maximumWhole !== 1 && payload.maximumWhole !== 2)
        || !whole(payload.divisions) || payload.divisions < 2 || payload.divisions > 12 || !fields(response, ['value'])
        || typeof response.value !== 'string' || !/^(0|[1-9]\d*)\/(0|[1-9]\d*)$/.test(response.value)) return 'invalid';
      const [numerator, denominator] = response.value.split('/').map(Number);
      if (!whole(numerator) || !whole(denominator) || denominator <= 0 || numerator > payload.maximumWhole * denominator
        || numerator * payload.divisions % denominator !== 0) return 'invalid';
      const units = numerator * payload.divisions / denominator;
      if (!whole(units) || units < 0 || units > payload.maximumWhole * payload.divisions) return 'invalid';
      if (rubric === undefined) return 'valid';
      if (!fields(rubric, ['targetNumerator', 'targetDenominator', 'toleranceUnits']) || !whole(rubric.targetNumerator)
        || !whole(rubric.targetDenominator) || rubric.targetDenominator <= 0 || !whole(rubric.toleranceUnits) || rubric.toleranceUnits < 0
        || rubric.targetNumerator > payload.maximumWhole * rubric.targetDenominator || rubric.targetNumerator * payload.divisions % rubric.targetDenominator !== 0) return 'invalid';
      const targetUnits = rubric.targetNumerator * payload.divisions / rubric.targetDenominator;
      return Math.abs(units - targetUnits) <= rubric.toleranceUnits ? 'met' : 'review';
    }
    case 'math.fraction-area.v2': {
      if (!fields(payload, ['minimumParts', 'maximumParts']) || !whole(payload.minimumParts) || !whole(payload.maximumParts)
        || payload.minimumParts < 2 || payload.maximumParts > 6 || payload.minimumParts > payload.maximumParts
        || !fields(response, ['n', 'd']) || !whole(response.n) || !whole(response.d) || response.d < payload.minimumParts
        || response.d > payload.maximumParts || response.n < 0 || response.n > response.d) return 'invalid';
      if (rubric === undefined) return 'valid';
      if (!fields(rubric, ['targetNumerator', 'targetDenominator']) || !whole(rubric.targetNumerator) || !whole(rubric.targetDenominator)
        || rubric.targetDenominator < payload.minimumParts || rubric.targetDenominator > payload.maximumParts
        || rubric.targetNumerator < 0 || rubric.targetNumerator > rubric.targetDenominator) return 'invalid';
      return response.n * rubric.targetDenominator === rubric.targetNumerator * response.d ? 'met' : 'review';
    }
    case 'math.bar-model.structure.v2': {
      if (!fields(payload, ['whole', 'difference']) || !whole(payload.whole) || !whole(payload.difference) || payload.whole <= payload.difference
        || !fields(response, ['model']) || (response.model !== 'comparison' && response.model !== 'part-whole')) return 'invalid';
      if (rubric === undefined) return 'valid';
      if (!fields(rubric, ['model']) || rubric.model !== 'comparison') return 'invalid';
      return response.model === rubric.model ? 'met' : 'review';
    }
    case 'math.bar-model.answer.v2': {
      if (!fields(payload, ['whole', 'difference']) || !whole(payload.whole) || !whole(payload.difference) || payload.whole <= payload.difference
        || !fields(response, ['value']) || typeof response.value !== 'string' || !/^(0|[1-9]\d*)$/.test(response.value)) return 'invalid';
      const value = Number(response.value); if (!whole(value) || value > payload.whole) return 'invalid';
      if (rubric === undefined) return 'valid';
      if (!fields(rubric, ['target']) || !whole(rubric.target) || rubric.target < 0 || rubric.target > payload.whole) return 'invalid';
      return value === rubric.target ? 'met' : 'review';
    }
    case 'math.schema-diagram.structure.v2': {
      if (!fields(payload, ['income', 'spending']) || !whole(payload.income) || !whole(payload.spending) || payload.income <= payload.spending
        || !fields(response, ['schema']) || (response.schema !== 'change' && response.schema !== 'compare')) return 'invalid';
      if (rubric === undefined) return 'valid';
      if (!fields(rubric, ['schema']) || rubric.schema !== 'change') return 'invalid';
      return response.schema === rubric.schema ? 'met' : 'review';
    }
    case 'math.schema-diagram.slots.v2': {
      if (!fields(payload, ['income', 'spending']) || !whole(payload.income) || !whole(payload.spending) || payload.income <= payload.spending
        || !fields(response, ['income', 'spending']) || typeof response.income !== 'string' || typeof response.spending !== 'string'
        || !/^(0|[1-9]\d*)$/.test(response.income) || !/^(0|[1-9]\d*)$/.test(response.spending)) return 'invalid';
      const income = Number(response.income), spending = Number(response.spending);
      if (!whole(income) || !whole(spending) || income > payload.income || spending > payload.income) return 'invalid';
      if (rubric === undefined) return 'valid';
      if (!fields(rubric, ['income', 'spending']) || !whole(rubric.income) || !whole(rubric.spending)) return 'invalid';
      return income === rubric.income && spending === rubric.spending ? 'met' : 'review';
    }
    case 'math.schema-diagram.answer.v2': {
      if (!fields(payload, ['income', 'spending']) || !whole(payload.income) || !whole(payload.spending) || payload.income <= payload.spending
        || !fields(response, ['value']) || typeof response.value !== 'string' || !/^(0|[1-9]\d*)$/.test(response.value)) return 'invalid';
      const value = Number(response.value); if (!whole(value) || value > payload.income) return 'invalid';
      if (rubric === undefined) return 'valid';
      if (!fields(rubric, ['target']) || !whole(rubric.target) || rubric.target < 0 || rubric.target > payload.income) return 'invalid';
      return value === rubric.target ? 'met' : 'review';
    }
    case 'math.worked-example.v2': {
      if (!fields(payload, ['response_step_ids']) || !Array.isArray(payload.response_step_ids)
        || payload.response_step_ids.length < 2 || payload.response_step_ids.length > 3
        || payload.response_step_ids.some((id) => typeof id !== 'string' || !/^[a-z0-9][a-z0-9._:-]{2,100}$/.test(id))
        || new Set(payload.response_step_ids).size !== payload.response_step_ids.length
        || !fields(response, ['values']) || !record(response.values)) return 'invalid';
      const ids = payload.response_step_ids as string[];
      const values = response.values;
      if (Object.keys(values).length !== ids.length || ids.some((id) => typeof values[id] !== 'string'
        || (values[id] as string).trim().length === 0 || (values[id] as string).trim().length > 40)) return 'invalid';
      if (rubric === undefined) return 'valid';
      if (!fields(rubric, ['expectedValues'])) return 'invalid';
      const expectedValues = rubric.expectedValues;
      if (!record(expectedValues) || Object.keys(expectedValues).length !== ids.length
        || ids.some((id) => typeof expectedValues[id] !== 'string'
          || (expectedValues[id] as string).trim().length === 0
          || (expectedValues[id] as string).trim().length > 40)) return 'invalid';
      return ids.every((id) => values[id] === expectedValues[id]) ? 'met' : 'review';
    }
      case 'math.function-machine.v2': {
        if (!fields(payload, ['multiplierMaximum', 'offsetMaximum', 'exampleInputs']) || !whole(payload.multiplierMaximum)
          || payload.multiplierMaximum < 1 || payload.multiplierMaximum > 12 || !whole(payload.offsetMaximum)
          || payload.offsetMaximum < 0 || payload.offsetMaximum > 100 || !Array.isArray(payload.exampleInputs)
          || payload.exampleInputs.length < 3 || payload.exampleInputs.length > 5
          || payload.exampleInputs.some((input) => !whole(input) || input < 0 || input > 12)
          || new Set(payload.exampleInputs).size !== payload.exampleInputs.length || !fields(response, ['multiplier', 'offset'])
        || typeof response.multiplier !== 'string' || typeof response.offset !== 'string'
        || !/^(0|[1-9]\d*)$/.test(response.multiplier) || !/^(0|[1-9]\d*)$/.test(response.offset)) return 'invalid';
        const exampleInputs = payload.exampleInputs as number[];
        const multiplier = Number(response.multiplier); const offset = Number(response.offset);
      if (!whole(multiplier) || multiplier < 1 || multiplier > payload.multiplierMaximum
        || !whole(offset) || offset < 0 || offset > payload.offsetMaximum) return 'invalid';
      if (rubric === undefined) return 'valid';
      if (!fields(rubric, ['multiplier', 'offset', 'heldOutInputs']) || !whole(rubric.multiplier)
        || rubric.multiplier < 1 || rubric.multiplier > payload.multiplierMaximum || !whole(rubric.offset)
        || rubric.offset < 0 || rubric.offset > payload.offsetMaximum || !Array.isArray(rubric.heldOutInputs)
        || rubric.heldOutInputs.length < 2 || rubric.heldOutInputs.length > 4
          || rubric.heldOutInputs.some((input) => !whole(input) || input < 0 || input > 24)
          || new Set(rubric.heldOutInputs).size !== rubric.heldOutInputs.length
          || rubric.heldOutInputs.some((input) => exampleInputs.includes(input))) return 'invalid';
      const expectedMultiplier = rubric.multiplier;
      const expectedOffset = rubric.offset;
      const heldOutInputs = rubric.heldOutInputs;
      return heldOutInputs.every((input) => multiplier * input + offset === expectedMultiplier * input + expectedOffset) ? 'met' : 'review';
    }
    case 'math.cpa-count.v2': {
      if (!fields(payload, ['left', 'right']) || !whole(payload.left) || !whole(payload.right)
        || payload.left < 1 || payload.right < 1 || payload.left > 20 || payload.right > 20
        || !fields(response, ['value']) || typeof response.value !== 'string' || !/^(0|[1-9]\d*)$/.test(response.value)) return 'invalid';
      const value = Number(response.value);
      if (!whole(value) || value < 0 || value > payload.left + payload.right) return 'invalid';
      if (rubric === undefined) return 'valid';
      if (!fields(rubric, ['target']) || !whole(rubric.target) || rubric.target !== payload.left + payload.right) return 'invalid';
      return value === rubric.target ? 'met' : 'review';
    }
    default: return 'invalid';
  }
}
